SELECT COUNT(*) AS matched, SUM(CASE WHEN d.amount IS DISTINCT FROM p.amount THEN 1 ELSE 0 END) AS differing, SUM(CASE WHEN d.amount IS NULL THEN 1 ELSE 0 END) AS dev_nulls, SUM(CASE WHEN p.amount IS NULL THEN 1 ELSE 0 END) AS prod_nulls FROM prod.orders p JOIN db.orders d ON p.id = d.id;
SELECT COUNT(*) AS prod_only FROM prod.orders p LEFT JOIN db.orders d ON p.id=d.id WHERE d.id IS NULL;
SELECT COUNT(*) AS dev_only FROM db.orders d LEFT JOIN prod.orders p ON p.id=d.id WHERE p.id IS NULL;
SELECT COUNT(*) AS rows, COUNT(DISTINCT id) AS ids FROM db.orders;

